import { parse as parseHtml } from 'node-html-parser';
import postcss from 'postcss';
import selectorParser from 'postcss-selector-parser';

/**
 * Strip pseudo-classes (:hover, :focus-within, ...) and pseudo-elements
 * (::before, ::first-line, ...) from a selector so it can be matched
 * against the static DOM.
 */
function stripPseudos(selector) {
  const processed = selectorParser().astSync(selector);
  processed.walkPseudos((pseudo) => {
    pseudo.remove();
  });
  return String(processed).trim();
}

/** True if at least one element in the document matches the stripped selector. */
function matchesDocument(htmlRoot, selector) {
  const stripped = stripPseudos(selector);
  if (!stripped) return false;
  try {
    return htmlRoot.querySelectorAll(stripped).length > 0;
  } catch {
    // Selector syntax node-html-parser cannot handle -> assume unused.
    return false;
  }
}

/** True when any comma-separated alternative of the rule matches. */
function ruleMatches(htmlRoot, rule) {
  return rule.selectors.some((sel) => matchesDocument(htmlRoot, sel));
}

const KEYFRAMES_RE = /^(?:-(?:webkit|moz|ms|o)-)?keyframes$/;

/**
 * Recursively prune a container's children according to usage.
 * Returns true if anything was removed (not used, but kept simple via mutation).
 */
function pruneContainer(container, htmlRoot) {
  for (const child of [...container.nodes]) {
    if (child.type === 'rule') {
      if (!ruleMatches(htmlRoot, child)) child.remove();
    } else if (child.type === 'atrule' && child.nodes) {
      // Nested containers (@media inside @supports, etc.)
      pruneContainer(child, htmlRoot);
      if (child.nodes.length === 0 && !KEYFRAMES_RE.test(child.name.toLowerCase())) {
        child.remove();
      }
    }
    // declarations and at-rules without blocks are left untouched here
  }
}

export function extract(html, css) {
  const htmlRoot = parseHtml(html);
  const ast = postcss.parse(css);

  for (const child of [...ast.nodes]) {
    if (child.type === 'atrule') {
      const name = child.name.toLowerCase();
      // Always keep keyframes and font-face.
      if (KEYFRAMES_RE.test(name) || name === 'font-face') continue;

      if (child.nodes) {
        // Conditional group rules (@media, @supports, ...): filter contents,
        // drop the whole at-rule if nothing survives.
        pruneContainer(child, htmlRoot);
        if (child.nodes.length === 0) child.remove();
        continue;
      }
      // Other block-less at-rules (@import, @charset): keep as-is.
      continue;
    }

    if (child.type === 'rule') {
      if (!ruleMatches(htmlRoot, child)) child.remove();
    }
    // top-level comments/declarations: keep
  }

  return ast.toString();
}

export default extract;

