import { describe, it, expect } from 'vitest';
import postcss from 'postcss';
import { extract } from '../src/extract.js';

/** Pull the exact selector list of every top-level rule (in order). */
function topSelectorLists(css) {
  const root = postcss.parse(css);
  return root.nodes
    .filter((n) => n.type === 'rule')
    .map((r) => r.selectors.join(', '));
}

function mediaBlocks(css) {
  const root = postcss.parse(css);
  return root.nodes.filter(
    (n) => n.type === 'atrule' && n.name === 'media'
  );
}

describe('critical css extraction', () => {
  // Fixture: one page + one stylesheet.
  const html = `
    <html>
      <body>
        <header class="site-header">
          <nav><a href="/" class="logo">Home</a></nav>
        </header>
        <main>
          <h1 id="title">Hello</h1>
          <p class="intro lead">Some text</p>
          <ul class="items"><li>one</li><li>two</li></ul>
        </main>
      </body>
    </html>
  `;
  const css = `
    body { margin: 0; }
    .site-header nav a.logo { color: rebeccapurple; }
    h1#title, .missing-class { font-size: 2rem; }
    p.intro { line-height: 1.5; }
    .lead, .not-on-page { font-weight: 700; }
    .items > li { list-style: none; }
    .unused-rule { color: red; }

    @media (min-width: 40em) {
      .items { display: flex; }
      .nope-also { display: none; }
    }

    /* entirely unused media query */
    @media print {
      .print-only-a { display: none; }
      .print-only-b { color: black; }
    }
  `;

  const out = extract(html, css);

  it('keeps exactly the used selectors, preserving order and original text', () => {
    expect(topSelectorLists(out)).toEqual([
      'body',
      '.site-header nav a.logo',
      'h1#title', // .missing-class alternative dropped, h1#title kept
      'p.intro',
      '.lead', // .not-on-page alternative dropped
      '.items > li',
    ]);
  });

  it('drops rules whose selectors never match', () => {
    expect(out).not.toContain('.unused-rule');
    expect(out).not.toContain('.not-on-page');
    expect(out).not.toContain('.missing-class');
  });

  it('drops an unused media query entirely', () => {
    expect(mediaBlocks(out)).toHaveLength(1);
    expect(out).not.toContain('@media print');
    expect(out).not.toContain('.print-only-a');
  });

  it('keeps used rules inside a surviving media query', () => {
    const [media] = mediaBlocks(out);
    expect(media.params).toBe('(min-width: 40em)');
    expect(topSelectorLists(media)).toEqual(['.items']);
  });
});

describe('pseudo handling', () => {
  const html = `
    <div>
      <button class="btn">Go</button>
      <a href="#" class="link">x</a>
    </div>
  `;
  const css = `
    .btn:hover { background: blue; }
    .btn:focus-visible::after { content: ''; }
    a.link::first-line { color: green; }
    .btn::before:hover { color: teal; }
  `;
  const out = extract(html, css);

  it('survives hover-only selectors via their stripped form (.btn:hover -> .btn)', () => {
    expect(topSelectorLists(out)).toContain('.btn:hover');
  });

  it('keeps pseudo-element selectors when the base matches', () => {
    expect(topSelectorLists(out)).toContain('a.link::first-line');
  });

  it('original selector text is preserved verbatim in output', () => {
    expect(out).toMatch(/\.btn:focus-visible::after\s*\{/);
    expect(out).toMatch(/\.btn::before:hover\s*\{/); // stripped form still matches .btn
  });
});

describe('always-kept at-rules', () => {
  const html = `<p>plain</p>`;
  const css = `
    @font-face {
      font-family: 'Never Used';
      src: url('/fonts/x.woff2') format('woff2');
    }
    @keyframes spin { to { transform: rotate(360deg); } }
    @keyframes -webkit-spin { to { transform: rotate(360deg); } }
    .nothing-here { color: pink; }
  `;
  const out = extract(html, css);

  it('keeps @font-face and @keyframes even with no matching elements', () => {
    expect(out).toContain("@font-face");
    expect(out).toContain('@keyframes spin');
    expect(out).toContain('@keyframes -webkit-spin');
    expect(out).not.toContain('.nothing-here');
  });
});

